import Sheet from '../components/Sheet.vue'
type StageBeat=Beat&{targetKind:'paragraph'|'message';targetRevision:number;variantId:string|null;personaName:string|null}
const store=useLocal(),route=useRoute(),router=useRouter(),assets=useAssetIndex(),chatMode=!!route.params.sessionId,storyId=String(route.params.storyId||''),sessionId=String(route.params.sessionId||''),branchId=typeof route.query.branch==='string'?route.query.branch:null
const story=ref<Document<LocalStory>|null>(null),chat=ref<Document<ChatSession>|null>(null),source=ref<{id:string;kind:'story'|'branch'|'session';revision:number}|null>(null),state=ref<Document<StageState>|null>(null),settings=ref(defaultStageSettings()),cards=ref<Document<CharacterCard>[]>([]),beats=ref<StageBeat[]>([]),position=ref(0),chapterIndex=ref(0),error=ref(''),loading=ref(true),playing=ref(false),speed=ref(1),revealed=ref(0),hidden=ref(false),logOpen=ref(false),settingsOpen=ref(false),correction=ref(false),correctCard=ref(''),expression=ref<typeof expressions[number]>('neutral'),backgroundUrl=ref(''),portraitUrl=ref(''),endChoice=ref(false),writingOpen=ref(false),systemReduced=ref(false),voices=ref<SpeechSynthesisVoice[]>([])
const current=computed(()=>beats.value[position.value]),cast=computed(()=>cards.value.filter(row=>state.value?.value.cardIds.includes(row.id))),speaker=computed(()=>{const beat=current.value;if(!beat)return null;const override=state.value?.value.overrides.find(row=>row.targetId===beat.paragraphId&&row.textHash===beat.sourceHash&&row.start===beat.start&&row.end===beat.end);return override?cards.value.find(row=>row.id===override.cardId)||null:cast.value.find(row=>row.value.identityId===beat.speakerId)||null}),speakerName=computed(()=>speaker.value?.value.name||current.value?.personaName||'旁白'),title=computed(()=>chat.value?.value.title||story.value?.value.title||'故事演出'),shown=computed(()=>current.value?.text.slice(0,revealed.value)||''),reduced=computed(()=>settings.value.reducedMotion||systemReduced.value),anchor=computed<ProgressAnchor|null>(()=>!chatMode&&current.value?{storyId,branchId,paragraphId:current.value.paragraphId,offset:current.value.end}:null)
const expressionNames={neutral:'平静',happy:'开心',sad:'难过',angry:'生气',surprised:'惊讶',shy:'害羞'}
let saveFailed=false,disposed=false,epoch=0,progressRevision=0,settingsRevision=0,timer:ReturnType<typeof setTimeout>|null=null,typing:ReturnType<typeof setTimeout>|null=null,queue=Promise.resolve(),visualEpoch=0,audioEpoch=0,audio:HTMLAudioElement|null=null,audioUrl='',jobs:Document<MediaJob>[]=[],touchX:number|null=null
const lifecycle=new AbortController(),speech=new SystemSpeech(()=>{})
async function commit(documents:Parameters<NonNullable<typeof store.vault>['commitBundle']>[1]){const vault=store.vault;if(!vault)throw Error('私人库已锁定');const operation=crypto.randomUUID(),hash=await sha256(canonical(documents));try{await vault.commitBundle(operation,documents,lifecycle.signal)}catch(e){if(!vault.unlocked||(await vault.receipt(operation))?.payloadHash!==hash)throw e}}
function stopAudio(){audioEpoch++;speech.stop();if(audio){audio.pause();audio.removeAttribute('src');audio.load();audio=null}if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=''}
function pause(){playing.value=false;if(timer)clearTimeout(timer);timer=null;stopAudio()}
function clearTyping(){if(typing)clearTimeout(typing);typing=null}
function schedule(){if(timer)clearTimeout(timer);timer=null;if(playing.value&&!saveFailed&&!document.hidden&&!loading.value&&!endChoice.value&&!logOpen.value&&!settingsOpen.value&&!correction.value&&revealed.value===(current.value?.text.length||0))timer=setTimeout(()=>void advance(true),settings.value.autoDelay/speed.value)}
function reveal(){clearTyping();revealed.value=0;const beat=current.value;if(!beat)return;if(reduced.value||settings.value.textMs===0){revealed.value=beat.text.length;schedule();return}const units=typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('zh',{granularity:'grapheme'}).segment(beat.text)].map(row=>row.index+row.segment.length):Array.from(beat.text).reduce<number[]>((all,unit)=>[...all,(all.at(-1)||0)+unit.length],[]);let i=0;const tick=()=>{if(disposed||current.value?.id!==beat.id)return;revealed.value=units[i++]||beat.text.length;if(i<units.length)typing=setTimeout(tick,settings.value.textMs/speed.value);else{typing=null;schedule()}};typing=setTimeout(tick,settings.value.textMs/speed.value)}
async function save(){const vault=store.vault,beat=current.value;if(!vault||!beat||!state.value)return;const cursor:StageState['cursor']={targetId:beat.paragraphId,targetKind:beat.targetKind,variantId:beat.variantId,offset:beat.start};queue=queue.then(async()=>{if(disposed||!vault.unlocked||store.vault!==vault)return;const row=state.value;if(!row)return;const docs:Parameters<typeof vault.commitBundle>[1]=[{kind:'settings',id:row.id,expectedRevision:row.revision,value:{...row.value,cursor}}];if(!chatMode)docs.push({kind:'progress',id:progressKey(storyId,branchId),expectedRevision:progressRevision,value:{storyId,branchId,paragraphId:beat.paragraphId,offset:beat.start,beatId:beat.id}});await commit(docs);state.value=(await vault.read<StageState>(row.id))!;if(!chatMode)progressRevision++;saveFailed=false}).catch(e=>{saveFailed=true;pause();clearTyping();if(!disposed)error.value=(e as {code?:string}).code==='REVISION_CONFLICT'?'另一处已更新演出进度，请恢复已保存位置':(e as Error).message});await queue}
async function recoverSaved(){const vault=store.vault,target=source.value;if(!vault||!target)return;pause();await queue;try{const row=await vault.read<StageState>(stageStateId(target.id));if(!row)throw Error('演出存档缺失');state.value=row;if(chatMode){position.value=Math.max(0,beats.value.findIndex(beat=>beat.paragraphId===row.value.cursor?.targetId));reveal()}else{const progress=await vault.read<ProgressAnchor>(progressKey(storyId,branchId));progressRevision=progress?.revision||0;const cursor=progress?{targetId:progress.value.paragraphId,targetKind:'paragraph' as const,variantId:null,offset:progress.value.offset}:row.value.cursor,index=cursor?story.value!.value.chapters.findIndex(c=>c.paragraphIds.includes(cursor.targetId)):0;await chapter(Math.max(0,index),cursor)}saveFailed=false;error.value='';void visuals()}catch(e){error.value=(e as Error).message}}
async function updateState(change:(value:StageState)=>void){const vault=store.vault;if(!vault||!state.value)return;pause();queue=queue.then(async()=>{const row=state.value;if(!row||disposed||!vault.unlocked)return;const value=JSON.parse(canonical(row.value)) as StageState;change(value);await commit([{kind:'settings',id:row.id,expectedRevision:row.revision,value}]);state.value=(await vault.read<StageState>(row.id))!}).catch(e=>{if(!disposed)error.value=(e as Error).message});await queue}
async function chapter(index:number,cursor?:StageState['cursor'],step=1){const vault=store.vault,book=story.value;if(!vault||!book||index<0||index>=book.value.chapters.length)return;const ticket=++epoch;loading.value=true;error.value='';stopAudio();try{const rows=await vault.readMany<Paragraph>(book.value.chapters[index]!.paragraphIds);if(disposed||ticket!==epoch||!vault.unlocked)return;const compiled=await compileParagraphsToBeats(rows.map(row=>row.value),cast.value.map(row=>({id:row.value.identityId,name:row.value.name,aliases:Array.isArray(row.value.data.aliases)?row.value.data.aliases.filter((v):v is string=>typeof v==='string'):[]})));if(disposed||ticket!==epoch)return;if(!compiled.beats.length){const next=index+step;if(next>=0&&next<book.value.chapters.length)await chapter(next,null,step);else{pause();endChoice.value=!chatMode}return}if(cursor&&cursor.targetKind==='paragraph'){const n=compiled.beats.findIndex(beat=>beat.paragraphId===cursor.targetId&&beat.start<cursor.offset&&beat.end>cursor.offset);if(n>=0){const beat=compiled.beats[n]!,offset=unicodeOffset(beat.text,cursor.offset-beat.start);if(offset>0&&offset<beat.text.length)compiled.beats.splice(n,1,{...beat,id:beat.id+':a',end:beat.start+offset,text:beat.text.slice(0,offset)},{...beat,id:beat.id+':b',start:beat.start+offset,text:beat.text.slice(offset)})}}beats.value=compiled.beats.map(beat=>({...beat,targetKind:'paragraph',targetRevision:rows.find(row=>row.id===beat.paragraphId)!.revision,variantId:null,personaName:null}));chapterIndex.value=index;position.value=Math.max(0,cursor?beats.value.findIndex(beat=>beat.paragraphId===cursor.targetId&&(beat.end>cursor.offset||beat.start===cursor.offset)):0);endChoice.value=false;reveal();void visuals()}catch(e){if(!disposed&&ticket===epoch){pause();error.value=(e as Error).message}}finally{if(ticket===epoch){loading.value=false;schedule()}}}
async function advance(automatic=false){if(loading.value||saveFailed||!current.value)return;if(!automatic&&revealed.value<current.value.text.length){clearTyping();revealed.value=current.value.text.length;schedule();return}stopAudio();if(position.value+1<beats.value.length)position.value++;else if(!chatMode&&story.value&&chapterIndex.value+1<story.value.value.chapters.length){await chapter(chapterIndex.value+1);void save();return}else{pause();endChoice.value=!chatMode;return}expression.value='neutral';reveal();void visuals();void save();if(settings.value.systemVoice)void voice();schedule()}
