async function media(type:'image'|'tts',regenerate=false){const vault=store.vault,link=sourceLink(type==='image'?'background':'speech'),beat=current.value;if(!vault||!link||!beat)return;pause();try{if(type==='image'&&!regenerate){const existing=assets.rows.value.find(row=>!row.value.retired&&row.value.links.some(l=>l.targetId===link.targetId&&l.targetRevision===link.targetRevision&&l.role===link.role&&l.paragraphId===link.paragraphId));if(existing){await router.push({path:'/local/gallery',query:{asset:existing.id}});return}}const destination=await composeMedia(vault,{signal:lifecycle.signal,type,prompt:beat.text,source:link});if(!disposed&&store.vault===vault&&vault.unlocked)await router.push(destination)}catch(e){if(!disposed)error.value=(e as Error).message}}
async function visuals(){const vault=store.vault,link=sourceLink('background'),ticket=++visualEpoch;for(const url of [backgroundUrl.value,portraitUrl.value])if(url)URL.revokeObjectURL(url);backgroundUrl.value='';portraitUrl.value='';if(!vault||!link)return;const background=[...assets.rows.value].reverse().find(row=>!row.value.retired&&row.value.mediaKind==='image'&&row.value.links.some(l=>l.targetId===link.targetId&&l.targetRevision===link.targetRevision&&l.role==='background'&&l.paragraphId===link.paragraphId)),card=speaker.value,binding=card?state.value?.value.portraits.find(row=>row.cardId===card.id&&row.expression===expression.value):null,portrait=assets.rows.value.find(row=>!row.value.retired&&row.value.mediaKind==='image'&&(binding?row.id===binding.assetId:!!card&&row.value.links.some(l=>l.targetId===card.id&&l.targetRevision===card.revision&&l.role==='portrait')));for(const [row,output] of [[background,backgroundUrl],[portrait,portraitUrl]] as const){if(!row)continue;try{const bytes=await assetBytes(vault,row.value);if(disposed||ticket!==visualEpoch||!vault.unlocked)return;output.value=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:row.value.mime}))}catch{}}}
async function voice(){const vault=store.vault,beat=current.value,link=sourceLink('speech');if(!vault||!beat||!link)return;stopAudio();const ticket=audioEpoch,job=jobs.find(row=>row.value.type==='tts'&&row.value.status==='completed'&&row.value.prompt===beat.text&&row.value.source?.targetId===link.targetId&&row.value.source.targetRevision===link.targetRevision&&row.value.source.paragraphId===link.paragraphId),asset=job?assets.rows.value.find(row=>row.id===job.value.outputAssetId&&!row.value.retired):null;try{if(asset){const bytes=await assetBytes(vault,asset.value);if(disposed||ticket!==audioEpoch||!vault.unlocked)return;audioUrl=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:asset.value.mime}));audio=new Audio(audioUrl);await audio.play()}else speech.speak(beat.text,{voice:settings.value.voice,rate:speed.value})}catch(e){if(!disposed)error.value=(e as Error).message}}
async function correct(){const beat=current.value;if(!beat)return;await updateState(value=>{value.overrides=value.overrides.filter(row=>!(row.targetId===beat.paragraphId&&row.textHash===beat.sourceHash&&row.start===beat.start&&row.end===beat.end));value.overrides.push({targetId:beat.paragraphId,targetKind:beat.targetKind,textHash:beat.sourceHash,start:beat.start,end:beat.end,cardId:correctCard.value||null})});correction.value=false;void visuals()}
async function toggleCard(id:string,enabled:boolean){await updateState(value=>{value.cardIds=enabled?[...value.cardIds,id]:value.cardIds.filter(v=>v!==id);if(!enabled){value.overrides=value.overrides.filter(row=>row.cardId!==id);value.portraits=value.portraits.filter(row=>row.cardId!==id)}});if(!chatMode)await chapter(chapterIndex.value,state.value?.value.cursor)}
async function bindPortrait(cardId:string,value:string){await updateState(state=>{state.portraits=state.portraits.filter(row=>row.cardId!==cardId||row.expression!==expression.value);if(value)state.portraits.push({cardId,expression:expression.value,assetId:value})});void visuals()}
async function saveSettings(){try{await commit([{kind:'settings',id:'settings:stage',expectedRevision:settingsRevision,value:JSON.parse(canonical(settings.value))}]);settingsRevision++;settingsOpen.value=false;reveal()}catch(e){error.value=(e as Error).message}}
function key(event:KeyboardEvent){if(event.target instanceof HTMLInputElement||event.target instanceof HTMLSelectElement||event.target instanceof HTMLTextAreaElement||settingsOpen.value||logOpen.value||correction.value||writingOpen.value)return;if(event.code==='Space'||event.key==='ArrowRight'){event.preventDefault();void advance()}else if(event.key==='ArrowLeft'){event.preventDefault();void previous()}else if(event.key.toLowerCase()==='a')auto();else if(event.key.toLowerCase()==='h')hidden.value=!hidden.value;else if(event.key.toLowerCase()==='l'){pause();logOpen.value=true}else if(event.key==='Escape')void leave()}
async function reloadChat(){const vault=store.vault;if(!chatMode||!vault||disposed)return;const ticket=++epoch,oldId=current.value?.paragraphId,oldPosition=position.value;loading.value=true;pause();clearTyping();revealed.value=0;try{const session=await vault.read<ChatSession>(sessionId);if(!session)throw Error('原会话已失效');const rows=await vault.readMany<ChatMessage>(session.value.messageIds),compiled:StageBeat[]=[];for(const row of rows.filter(r=>!r.value.hidden)){const text=selectedText(row.value);compiled.push({id:(await sha256(row.id+':'+row.value.selectedVariantId)).slice(0,32),paragraphId:row.id,start:0,end:text.length,text,sourceHash:await sha256(text),speakerId:row.value.speakerId,confidence:1,kind:row.value.role==='assistant'?'dialogue':'narration',targetKind:'message',targetRevision:row.revision,variantId:row.value.selectedVariantId,personaName:row.value.role==='user'?row.value.personaName||session.value.persona.name:null})}if(disposed||ticket!==epoch||!vault.unlocked)return;chat.value=session;source.value={id:session.id,kind:'session',revision:session.revision};beats.value=compiled;const found=compiled.findIndex(b=>b.paragraphId===oldId);position.value=found>=0?found:Math.min(oldPosition,Math.max(0,compiled.length-1));reveal();void visuals()}catch(e){if(!disposed&&ticket===epoch)error.value=(e as Error).message}finally{if(ticket===epoch)loading.value=false}}
function privateChanged(event:Event){const detail=(event as CustomEvent<{vaultId:string;kinds:string[];ids:string[]}>).detail;if(chatMode&&store.vault?.id===detail?.vaultId&&(detail.kinds.includes('message')||detail.kinds.includes('session')))void reloadChat()}
function visibility(){if(document.hidden)pause()}
function touchStart(event:TouchEvent){touchX=event.touches.length===1?event.touches[0]!.clientX:null}
function touchEnd(event:TouchEvent){if(touchX!==null&&event.changedTouches.length===1){const delta=event.changedTouches[0]!.clientX-touchX;if(Math.abs(delta)>90)delta>0?void previous():void advance()}touchX=null}
watch(()=>[assets.rows.value,expression.value],()=>void visuals())
onMounted(async()=>{window.addEventListener('reader-private-commit',privateChanged);window.addEventListener('keydown',key);document.addEventListener('visibilitychange',visibility);systemReduced.value=matchMedia('(prefers-reduced-motion: reduce)').matches;voices.value='speechSynthesis' in window?speechSynthesis.getVoices():[];try{const vault=store.vault;if(!vault)return;const prefs=await vault.read<StageSettings>('settings:stage');if(prefs){settings.value=prefs.value;settingsRevision=prefs.revision}cards.value=await vault.list<CharacterCard>('card');if(chatMode){const row=await vault.read<ChatSession>(sessionId);if(!row||row.kind!=='session')throw Error('找不到这段会话');chat.value=row;source.value={id:row.id,kind:'session',revision:row.revision};cards.value=row.value.cards.map(card=>({id:card.id,kind:'card',revision:card.revision,value:card.value,updatedAt:row.updatedAt}))}else{const line=await readingLine(vault,storyId,branchId);story.value=line.line;source.value={id:(line.branch||line.story).id,kind:line.branch?'branch':'story',revision:(line.branch||line.story).revision};const progress=await vault.read<ProgressAnchor>(progressKey(storyId,branchId));progressRevision=progress?.revision||0;if(progress)chapterIndex.value=Math.max(0,story.value.value.chapters.findIndex(c=>c.paragraphIds.includes(progress.value.paragraphId)))}
 const target=source.value!,id=stageStateId(target.id);state.value=await vault.read<StageState>(id);if(!state.value){const text=chatMode?'':(await vault.readMany<Paragraph>(story.value!.value.chapters[chapterIndex.value]!.paragraphIds)).map(r=>r.value.text).join('\n'),value:StageState={assetType:'stage-state',targetId:target.id,targetKind:target.kind,cardIds:cards.value.filter(row=>chatMode||text.includes(row.value.name)).slice(0,100).map(row=>row.id),cursor:null,overrides:[],portraits:[]};await commit([{kind:'settings',id,expectedRevision:0,value}]);state.value=(await vault.read<StageState>(id))!}jobs=await vault.list<MediaJob>('mediaJob')
 if(chatMode){const messages=await vault.readMany<ChatMessage>(chat.value!.value.messageIds),compiled:StageBeat[]=[];for(const row of messages.filter(row=>!row.value.hidden)){const text=selectedText(row.value);compiled.push({id:(await sha256(row.id+':'+row.value.selectedVariantId)).slice(0,32),paragraphId:row.id,start:0,end:text.length,text,sourceHash:await sha256(text),speakerId:row.value.speakerId,confidence:1,kind:row.value.role==='assistant'?'dialogue':'narration',targetKind:'message',targetRevision:row.revision,variantId:row.value.selectedVariantId,personaName:row.value.role==='user'?row.value.personaName||chat.value!.value.persona.name:null})}beats.value=compiled;position.value=Math.max(0,compiled.findIndex(beat=>beat.paragraphId===state.value?.value.cursor?.targetId));loading.value=false;reveal();void visuals()}else{const progress=await vault.read<ProgressAnchor>(progressKey(storyId,branchId)),requested=typeof route.query.paragraph==='string'?route.query.paragraph:null;if(requested&&story.value!.value.paragraphIds.includes(requested))chapterIndex.value=Math.max(0,story.value!.value.chapters.findIndex(c=>c.paragraphIds.includes(requested)));const cursor=requested&&story.value!.value.paragraphIds.includes(requested)?{targetId:requested,targetKind:'paragraph' as const,variantId:null,offset:Number.isSafeInteger(Number(route.query.offset))&&Number(route.query.offset)>=0?Number(route.query.offset):0}:progress?{targetId:progress.value.paragraphId,targetKind:'paragraph' as const,variantId:null,offset:progress.value.offset}:state.value.value.cursor;await chapter(chapterIndex.value,cursor)}await save()
 }catch(e){if(!disposed){error.value=(e as Error).message;loading.value=false}}})
onBeforeRouteLeave(async()=>{pause();clearTyping();await save();return !saveFailed})
onUnmounted(()=>{disposed=true;lifecycle.abort();pause();clearTyping();visualEpoch++;for(const url of [backgroundUrl.value,portraitUrl.value])if(url)URL.revokeObjectURL(url);beats.value=[];cards.value=[];state.value=null;jobs=[];window.removeEventListener('reader-private-commit',privateChanged);window.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',visibility)})
</script>
<template><section class="final-stage final-vn" :class="{'reduce-motion':reduced}" @touchstart.passive="touchStart" @touchend.passive="touchEnd"><div class="final-vn-backdrop"><Transition name="stage-fade"><img v-if="backgroundUrl" :key="current?.paragraphId" :src="backgroundUrl" alt=""/></Transition><img v-if="!backgroundUrl&&story?.value.coverAssetId==='final-cover-fog-v1'" src="/assets/original/final-product/harbor-dawn-1920.webp" alt=""/><div v-if="!backgroundUrl" class="final-vn-atmosphere"/></div><header class="final-stage-header"><button class="final-icon-button" :aria-label="chatMode?'返回聊天':'返回阅读'" @click="leave"><ArrowLeft :size="22"/></button><div class="final-vn-title"><span>{{title}}</span><small>{{chatMode?'对话舞台':story?.value.chapters[chapterIndex]?.title}}</small></div><button class="final-icon-button" aria-label="演出日志" @click="pause();logOpen=true"><History :size="20"/></button><button class="final-icon-button" aria-label="舞台设置" @click="pause();settingsOpen=true"><Settings2 :size="20"/></button></header><div class="final-vn-character" aria-hidden="true"><Transition name="stage-portrait"><img v-if="portraitUrl" :key="speaker?.id+':'+expression" :src="portraitUrl" alt=""/><div v-else-if="speaker" :key="speaker.id" class="final-vn-monogram"><span>{{speaker.value.name.slice(0,1)}}</span></div></Transition></div><button v-if="hidden" class="final-vn-show" @click="hidden=false"><Eye :size="18"/>显示台词</button><div v-else class="final-stage-dialogue final-vn-dialogue" :style="{fontSize:settings.fontSize+'px'}"><p v-if="error" class="final-error" role="alert">{{error}}<button v-if="saveFailed" @click="recoverSaved">恢复已保存位置</button><button v-else @click="error=''">关闭提示</button></p><p v-if="loading" role="status">正在展开故事…</p><template v-else><div class="final-vn-speaker"><button aria-label="纠正这句说话者" @click="pause();correctCard=speaker?.id||'';correction=true">{{speakerName}}</button><small>{{current?.confidence===0&&!speaker?'':''}}</small><button class="final-icon-button" aria-label="隐藏台词" @click="hidden=true"><EyeOff :size="17"/></button></div><button class="final-vn-line" aria-label="显示全句或推进台词" @click="advance()"><span aria-hidden="true">{{shown||' '}}</span><span class="sr-only">{{current?.text||'暂无台词'}}</span><ChevronRight v-if="current&&revealed===current.text.length" :size="20" class="final-vn-next-marker"/></button></template><div v-if="endChoice" class="final-vn-choice"><button class="final-primary" @click="endChoice=false;writingOpen=true">从这里写</button><button @click="leave">回到故事</button></div><div class="final-stage-controls"><button :disabled="loading" @click="previous">上一句</button><span class="final-subtle">{{beats.length?position+1:0}} / {{beats.length}}</span><button aria-label="快进到下一句" :disabled="loading" @click="revealed=current?.text.length||0;advance(true)"><FastForward :size="18"/></button><button aria-label="播放本句配音" :disabled="!current" @click="voice"><Volume2 :size="18"/></button><button :aria-pressed="playing" :aria-label="playing?'暂停自动播放':'自动播放'" @click="auto"><Pause v-if="playing" :size="18"/><Play v-else :size="18"/><span>AUTO</span></button><button class="final-primary" :disabled="loading||!current" @click="advance()">下一句<ChevronRight :size="18"/></button></div></div><Sheet v-if="logOpen" title="演出日志" @close="logOpen=false"><div class="final-vn-log"><button v-for="(beat,n) in beats.slice(0,position+1)" :key="beat.id" :aria-current="n===position?'step':undefined" @click="jump(n)"><small>{{cast.find(row=>row.value.identityId===beat.speakerId)?.value.name||beat.personaName||'旁白'}}</small><p>{{beat.text}}</p></button><RouterLink v-if="chatMode" :to="'/local/chat/'+sessionId">回到原会话继续发言</RouterLink></div></Sheet><Sheet v-if="settingsOpen" title="舞台设置" @close="settingsOpen=false"><form class="final-card-form" @submit.prevent="saveSettings"><label>文字速度<input v-model.number="settings.textMs" aria-label="台词每字间隔" type="range" min="0" max="150"><small>{{settings.textMs===0?'立即显示':settings.textMs+' 毫秒 / 字'}}</small></label><label>字号<input v-model.number="settings.fontSize" aria-label="舞台字号" type="range" min="16" max="40"></label><label>AUTO 停留<input v-model.number="settings.autoDelay" aria-label="自动停留毫秒" type="number" min="500" max="10000"></label><label>播放速度<select v-model.number="speed"><option :value="1">1×</option><option :value="1.5">1.5×</option><option :value="2">2×</option></select></label><label class="final-check"><input v-model="settings.reducedMotion" type="checkbox">减少动态</label><label class="final-check"><input v-model="settings.systemVoice" type="checkbox">推进时朗读台词</label><label>系统音色<select v-model="settings.voice"><option value="">设备默认</option><option v-for="voice in voices" :key="voice.voiceURI" :value="voice.voiceURI">{{voice.name}}</option></select></label><fieldset v-if="cards.length"><legend>演出人物</legend><label v-for="card in cards" :key="card.id" class="final-check"><input type="checkbox" :checked="state?.value.cardIds.includes(card.id)" @change="toggleCard(card.id,($event.target as HTMLInputElement).checked)">{{card.value.name}}</label></fieldset><template v-if="speaker"><label>当前表情<select v-model="expression" aria-label="当前角色表情"><option v-for="v in expressions" :key="v" :value="v">{{expressionNames[v]}}</option></select></label><label>关联立绘<select aria-label="关联表情立绘" :value="state?.value.portraits.find(row=>row.cardId===speaker?.id&&row.expression===expression)?.assetId||''" @change="bindPortrait(speaker!.id,($event.target as HTMLSelectElement).value)"><option value="">使用默认形象</option><option v-for="asset in assets.rows.value.filter(row=>!row.value.retired&&row.value.mediaKind==='image')" :key="asset.id" :value="asset.id">{{asset.value.name}}</option></select></label></template><button class="final-primary">保存设置</button></form><div class="final-grid-actions"><button @click="media('image')">本场景配图</button><button @click="media('image',true)">制作另一幅场景</button><button @click="media('tts')">制作本句配音</button></div></Sheet><Sheet v-if="correction" title="这句由谁说？" @close="correction=false"><form class="final-card-form" @submit.prevent="correct"><blockquote>{{current?.text}}</blockquote><select v-model="correctCard" aria-label="纠正说话者"><option value="">旁白</option><option v-for="card in cast" :key="card.id" :value="card.id">{{card.value.name}}</option></select><details><summary>原文位置</summary><p>{{current?.paragraphId}} · {{current?.start}}—{{current?.end}}</p><p>UTF16 · {{current?.confidence===1?'规则明确归因':'未作强归因'}}</p></details><button class="final-primary">保存局部纠正</button></form></Sheet><div v-if="!chatMode" class="final-vn-writing"><WritingPanel :story-id="storyId" :branch-id="branchId" :anchor="anchor" :open="writingOpen" :intent-id="source&&current?source.id+':'+current.id:undefined" return-to="stage" @close="writingOpen=false"/></div></section></template>
<style scoped>.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.final-vn{isolation:isolate;overflow:hidden;background:var(--wash);color:var(--ink);height:100dvh;min-height:0}.final-vn-backdrop{position:absolute;inset:0;z-index:-2;overflow:hidden;background:var(--wash)}.final-vn-backdrop>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.final-vn-backdrop:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(252,249,243,.6),transparent 35%,rgba(23,35,31,.1))}.final-vn-atmosphere{position:absolute;inset:0;background:radial-gradient(ellipse at 65% 20%,var(--accent-soft),transparent 55%),linear-gradient(160deg,var(--paper),var(--wash));animation:stage-breathe 12s ease-in-out infinite alternate}.final-vn .final-stage-header{background:color-mix(in srgb,var(--paper) 80%,transparent);backdrop-filter:blur(18px);z-index:3;position:absolute;top:0;left:0;right:0;display:flex;gap:12px;align-items:center;padding:12px 20px;border-bottom:1px solid var(--edge)}.final-vn-title{flex:1;min-width:0;display:grid;gap:5px;text-align:center}.final-vn-title span{font:500 18px var(--font-serif);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.final-vn-title small{font-size:11px;color:var(--muted)}.final-vn-character{position:absolute;inset:90px 12% 22%;display:flex;justify-content:center;align-items:flex-end;pointer-events:none}.final-vn-character img{height:100%;max-width:90%;object-fit:contain;object-position:bottom;filter:drop-shadow(0 15px 25px rgba(15,35,28,.12))}.final-vn-monogram{height:330px;width:230px;border-radius:140px 140px 10px 10px;background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 12%,var(--paper)),transparent);display:grid;place-items:center;opacity:.7}.final-vn-monogram span{font:100px var(--font-serif);color:var(--accent);opacity:.45}.final-vn .final-vn-dialogue{width:auto;max-width:none;margin:0;position:absolute;left:max(24px,calc((100vw - 1050px)/2));right:max(24px,calc((100vw - 1050px)/2));bottom:max(24px,env(safe-area-inset-bottom));background:color-mix(in srgb,var(--paper) 94%,transparent);backdrop-filter:blur(22px);border:1px solid var(--edge);border-radius:20px;padding:22px 28px;max-height:55dvh;overflow-y:auto;box-shadow:0 16px 60px rgba(18,31,25,.07);z-index:2}.final-vn-speaker{display:flex;align-items:center;gap:16px;font-size:13px}.final-vn-speaker>button:first-child{padding:5px 0;border:0;background:transparent;color:var(--accent);font-weight:600;font-size:16px;min-height:36px}.final-vn-speaker small{flex:1}.final-vn-speaker .final-icon-button{margin-left:auto}.final-vn-line{display:block;width:100%;font:inherit;line-height:1.8;white-space:pre-wrap;text-align:left;border:0;padding:12px 0;background:transparent;min-height:110px;max-height:28dvh;overflow:auto;position:relative;overflow-wrap:anywhere;cursor:pointer;justify-content:normal}.final-vn-next-marker{display:block;margin-left:auto;color:var(--accent);animation:stage-marker 1.5s ease-in-out infinite}.final-vn .final-stage-controls{font:12px var(--font-ui);display:flex;flex-wrap:wrap;gap:8px;align-items:center;border-top:1px solid var(--edge);padding-top:14px;margin-top:8px}.final-vn .final-stage-controls .final-primary{margin-left:auto}.final-vn .final-stage-controls>button{min-height:44px;padding:8px 12px}.final-vn-show{position:absolute;bottom:30px;right:30px;background:var(--paper);z-index:3}.final-vn-log{display:grid;gap:12px}.final-vn-log button{text-align:left;display:grid;justify-content:stretch;gap:8px}.final-vn-log p{margin:0;white-space:pre-wrap;line-height:1.8}.final-vn-log small{color:var(--accent)}.final-vn-log button[aria-current]{border-color:var(--accent)}.final-vn-choice{display:flex;gap:12px;justify-content:center;margin:16px 0}.final-vn-writing{position:absolute;right:18px;top:90px;width:min(560px,calc(100vw - 36px));max-height:calc(100dvh - 150px);overflow:auto;z-index:5;background:var(--paper);border-radius:16px}.final-vn-writing:empty{display:none}.final-vn-writing :deep(.final-writing-output){margin:0;padding:20px;border-top:0;font-size:18px;line-height:1.8}.stage-fade-enter-active,.stage-fade-leave-active{transition:opacity .5s}.stage-fade-enter-from,.stage-fade-leave-to{opacity:0}.stage-portrait-enter-active,.stage-portrait-leave-active{transition:opacity .3s,transform .3s}.stage-portrait-enter-from,.stage-portrait-leave-to{opacity:0;transform:translateY(12px)}.reduce-motion *{animation:none!important;transition:none!important}@keyframes stage-breathe{to{transform:scale(1.025)}}@keyframes stage-marker{50%{transform:translateX(4px);opacity:.5}}@media(max-width:650px){.final-vn .final-stage-header{padding:10px 12px;gap:6px}.final-vn-title span{font-size:16px}.final-vn .final-vn-dialogue{left:12px;right:12px;bottom:max(12px,env(safe-area-inset-bottom));padding:16px 18px;max-height:58dvh}.final-vn-line{min-height:90px;max-height:30dvh}.final-vn-character{inset:90px 8% 30%}.final-vn .final-stage-controls>button{padding:8px}.final-stage-controls>span{display:none}.final-vn .final-stage-controls{gap:6px}.final-vn-monogram{width:180px;height:250px}.final-vn-writing{max-height:calc(100dvh - 120px)}}@media(orientation:landscape) and (max-height:550px){.final-vn .final-vn-dialogue{bottom:8px;max-height:60dvh;padding:12px 20px;left:10%;right:10%}.final-vn-line{min-height:50px;max-height:21dvh}.final-vn .final-stage-header{padding:5px 15px}.final-vn-character{inset:55px 15% 12%}.final-vn .final-stage-controls{margin-top:0;padding-top:8px}}</style>
